{
 "genere": "prevedi",
 "titolo": "Ripasso: Oggetti fisici e zone in 3D",
 "consegna": "Leggi ogni pezzo di codice e scrivi cosa restituisce `run()`, senza eseguirlo. Poi confronta con la risposta vera.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends RefCounted


func run():
	var objects_inside: int = 0
	objects_inside += 1
	var is_active_1: bool = (objects_inside > 0)
	objects_inside += 1
	objects_inside -= 1
	var is_active_2: bool = (objects_inside > 0)
	return is_active_2
",
   "domanda": "Quanto vale `is_active_2` alla fine?",
   "spiegazione": "Gli oggetti dentro partono da 0, salgono a 1 (zona attiva), poi a 2, e tornano a 1 quando uno esce. Poiché `objects_inside` è ancora maggiore di 0, la zona resta attiva (`true`)."
  },
  {
   "codice": "extends RefCounted


func run():
	var base_impulse: float = 5.0
	var multiplier: float = 2.0
	var final_impulse: Vector3 = Vector3(0, 0, base_impulse * multiplier)
	return final_impulse.z
",
   "domanda": "Quanto vale la coordinata z di `final_impulse`?",
   "spiegazione": "Il vettore 3D viene creato moltiplicando `base_impulse` per `multiplier` sulla coordinata z: `5.0 * 2.0` dà `10.0`."
  },
  {
   "codice": "extends RefCounted


func run():
	var objects_inside: int = 0
	var activations: int = 0
	objects_inside += 1
	if objects_inside == 1:
		activations += 1
	objects_inside += 1
	if objects_inside == 1:
		activations += 1
	objects_inside -= 1
	if objects_inside == 0:
		activations += 1
	return activations
",
   "domanda": "Quanto vale `activations` alla fine?",
   "spiegazione": "All'inizio `objects_inside` diventa 1 e fa scattare l'attivazione (`activations` = 1). Quando entra il secondo sale a 2 (la condizione `== 1` è falsa). Quando il primo esce scende a 1 (la condizione `== 0` è falsa). L'attivazione rimane 1."
  },
  {
   "codice": "extends RefCounted


func run():
	var push_dir := Vector3(1, 0, 0)
	var strength: float = 4.5
	var impulse := push_dir * strength
	return impulse.x
",
   "domanda": "Quanto vale `impulse.x`?",
   "spiegazione": "Moltiplicando il vettore direzionale `Vector3(1, 0, 0)` per la forza `4.5`, la componente x diventa `1 * 4.5 = 4.5`."
  },
  {
   "codice": "extends RefCounted


func run():
	var is_character: bool = false
	var is_rigid: bool = true
	var blocks_pressure: bool = is_character or is_rigid
	return blocks_pressure
",
   "domanda": "Quanto vale `blocks_pressure`?",
   "spiegazione": "La variabile usa l'operatore `or` tra `is_character` (falso) e `is_rigid` (vero). Poiché almeno una delle due condizioni è vera, il risultato è `true`."
  }
 ]
